    client.set = AsyncMock(side_effect=ConnectionError('Redis cluster unreachable'))
    return client


@pytest.fixture
def l1_with_data():
    cache = MagicMock()
    cache.get = MagicMock(return_value={
        'value': '{"order_id": 555}',
        'ttl_remaining': 120,
        'cache_tier': 'L1',
    })
    return cache


@pytest.mark.asyncio
async def test_circuit_breaker_redis_unavailable(redis_unavailable, l1_with_data):
    """
    When Redis is unavailable:
    1. Circuit breaker opens after threshold failures
    2. Service falls back to L1 cache gracefully
    3. No exception propagates to the caller
    4. Response indicates degraded mode (L1 only)
    """
    namespace = 'orders'
    key = 'order:555'
    cache_key = f'{namespace}:{key}'
    cb = MockCircuitBreaker(failure_threshold=3)

    # Simulate repeated Redis failures tripping the circuit breaker
    for i in range(3):
        try:
            await redis_unavailable.get(cache_key)
        except ConnectionError:
            cb.record_failure()

    assert cb.is_open(), (
        f'Circuit breaker should be OPEN after 3 failures, state={cb.state}'
    )

    # With circuit open, fall back to L1 — no exception should propagate
    exception_propagated = False
    result = None
    try:
        if cb.is_open():
            # Bypass Redis entirely, use L1
            result = l1_with_data.get(cache_key)
        else:
            result = await redis_unavailable.get(cache_key)
    except Exception as e:
        exception_propagated = True

    assert not exception_propagated, (
        'Circuit breaker should prevent exception propagation to callers'
    )
    assert result is not None, (
        'Should return L1 result even when Redis is unavailable'
    )
    assert result['cache_tier'] == 'L1', (
        f"Expected L1 fallback, got tier='{result['cache_tier']}'"
    )
    assert result['value'] == '{"order_id": 555}', (
        'L1 fallback value does not match expected'
    )

    # Verify Redis was called exactly 3 times (the threshold), not more
    assert redis_unavailable.get.call_count == 3, (
        f'Expected exactly 3 Redis calls before circuit opened, '
        f'got {redis_unavailable.get.call_count}'
    )

import pytest
from unittest.mock import MagicMock


class MockMetricsSnapshot:
    """Simulates a Pydantic MetricsSnapshot model."""
    def __init__(self, l1_hits, l2_hits, misses, evictions, avg_latency_ms):
        self.l1_hits = l1_hits
        self.l2_hits = l2_hits
        self.misses = misses
        self.evictions = evictions
        self.avg_latency_ms = avg_latency_ms
        self.total_requests = l1_hits + l2_hits + misses

    @property
    def l1_hit_rate(self):
        if self.total_requests == 0:
            return 0.0
        return round(self.l1_hits / self.total_requests, 4)

    @property
    def l2_hit_rate(self):
        if self.total_requests == 0:
            return 0.0
        return round(self.l2_hits / self.total_requests, 4)

    @property
    def overall_hit_rate(self):
        if self.total_requests == 0:
            return 0.0
        return round((self.l1_hits + self.l2_hits) / self.total_requests, 4)

    @property
    def miss_rate(self):
        return round(1.0 - self.overall_hit_rate, 4)


def test_metrics_endpoint_returns_hit_rates():
    """
    GET /api/v1/cache/{namespace}/metrics must return:
    1. Correct L1 and L2 hit rates
    2. Overall hit rate and miss rate summing to 1.0
    3. Eviction count
    4. Average latency
    5. Total request count
    """
    snapshot = MockMetricsSnapshot(
        l1_hits=7500,
        l2_hits=1800,
        misses=700,
        evictions=42,
        avg_latency_ms=0.8,
    )

    # Validate total
    assert snapshot.total_requests == 10000, (
        f'Expected total_requests=10000, got {snapshot.total_requests}'
    )

    # Validate L1 hit rate
    assert snapshot.l1_hit_rate == 0.75, (
        f'Expected L1 hit rate=0.75, got {snapshot.l1_hit_rate}'
    )

    # Validate L2 hit rate
    assert snapshot.l2_hit_rate == 0.18, (
        f'Expected L2 hit rate=0.18, got {snapshot.l2_hit_rate}'
    )

    # Validate overall hit rate
    assert snapshot.overall_hit_rate == 0.93, (
        f'Expected overall hit rate=0.93, got {snapshot.overall_hit_rate}'
    )

    # Hit rate + miss rate must equal 1.0
    total_rate = round(snapshot.overall_hit_rate + snapshot.miss_rate, 4)
    assert total_rate == 1.0, (
        f'Hit rate + miss rate should equal 1.0, got {total_rate}'
    )

    # Validate evictions
    assert snapshot.evictions == 42, (
        f'Expected evictions=42, got {snapshot.evictions}'
    )

    # Validate latency
    assert snapshot.avg_latency_ms < 1.0, (
        f'Average latency {snapshot.avg_latency_ms}ms should be sub-millisecond for L1-heavy workload'
    )

    # Edge case: zero requests
    empty_snapshot = MockMetricsSnapshot(0, 0, 0, 0, 0.0)
    assert empty_snapshot.l1_hit_rate == 0.0, 'Zero-request hit rate should be 0.0'
    assert empty_snapshot.overall_hit_rate == 0.0, 'Zero-request overall hit rate should be 0.0'
    assert empty_snapshot.miss_rate == 1.0, (
        f'Zero-request miss rate should be 1.0, got {empty_snapshot.miss_rate}'
    )
